<?php
require_once __DIR__.'/../../services/HistoricoEntidade.php';
require_once __DIR__.'/../../controllers/GraficoController.php';
$h=new HistoricoEntidade($pdo);$erroHistorico='';$series=[];
try {
    $f=$h->filtros(array_replace($_GET,$escopoHistorico));
    $historicoLeituras=$h->consultar($f,'leituras',0,25);$historicoAlertas=$h->consultar($f,'alertas',0,5);
    foreach(array_keys(SensorModel::TIPOS) as $tipo){if($f['sensor']&&$f['sensor']!==$tipo)continue;$serie=(new GraficoController($pdo))->serieJson(array_replace($f,['sensor'=>$tipo]));if($serie['total'])$series[$tipo]=$serie;}
} catch(InvalidArgumentException $e){$erroHistorico=$e->getMessage();}
?>
<section class="card"><h2>Histórico ambiental</h2><form method="get" class="filtros-linha"><input type="hidden" name="id" value="<?= $id ?>"><label>Data inicial<input type="date" name="data_ini" value="<?= escapar(is_string($_GET['data_ini']??null)?$_GET['data_ini']:'') ?>"></label><label>Data final<input type="date" name="data_fim" value="<?= escapar(is_string($_GET['data_fim']??null)?$_GET['data_fim']:'') ?>"></label>
<?php if(isset($escopoHistorico['estoque_id'])): ?><label>Sensor<select name="sensor_id"><option value="0">Todos os sensores do estoque</option><?php $q=$pdo->prepare('SELECT DISTINCT s.id,s.nome FROM sensores s LEFT JOIN leitura_sensor l ON l.sensor_id=s.id WHERE s.estoque_id=? OR l.estoque_id=? ORDER BY s.nome');$q->execute([$id,$id]);foreach($q->fetchAll() as $op): ?><option value="<?= (int)$op['id'] ?>" <?= (int)($_GET['sensor_id']??0)===(int)$op['id']?'selected':'' ?>><?= escapar($op['nome']) ?></option><?php endforeach ?></select></label><?php endif ?><button>Aplicar período</button><a class="btn-secundario" href="?id=<?= $id ?>">Todo o histórico</a></form></section>
<?php if($erroHistorico): ?><p class="msg-erro" role="alert"><?= escapar($erroHistorico) ?></p><?php else: ?>
<div class="actions"><a class="btn-secundario" href="<?= urlApp('routes/exportar.php').'?'.escapar(http_build_query($f+['entidade'=>$entidade,'id'=>$id,'formato'=>'csv'])) ?>">Baixar informações em CSV</a><a class="btn-secundario" href="<?= urlApp('routes/exportar.php').'?'.escapar(http_build_query($f+['entidade'=>$entidade,'id'=>$id,'formato'=>'pdf'])) ?>">Baixar informações em PDF</a></div><p class="texto-auxiliar">Inclui identificação, sensores, configuração, resumo, todas as leituras e todos os alertas do período escolhido.</p>
<div class="graficos-grid"><?php foreach($series as $tipo=>$serie): ?><section class="card"><h2><?= escapar(SensorModel::rotuloComUnidade($tipo)) ?></h2><div class="grafico-area"><canvas id="historico-<?= $tipo ?>" role="img" aria-label="Histórico de <?= escapar(SensorModel::rotulo($tipo)) ?>"></canvas></div><p>Histórico: médias por intervalo e limites vigentes em cada leitura.</p></section><?php endforeach ?></div>
<?php if(!$series): ?><p class="estado-vazio">Nenhuma leitura no período selecionado.</p><?php endif ?>
<section class="card"><h2>Alertas recentes</h2><p><?= $historicoAlertas['total'] ?> ocorrências no período. As cinco mais recentes aparecem primeiro.</p><div id="historico-alertas" class="alertas-grade"><?php $permitirAcoes=false;foreach($historicoAlertas['registros'] as $a)require __DIR__.'/cartao_alerta.php'; ?></div><?php if(!$historicoAlertas['total']): ?><p class="estado-vazio">Nenhum alerta encontrado.</p><?php endif ?><?php if($historicoAlertas['total']>5): ?><button type="button" class="btn-secundario" data-carregar="<?= urlApp('routes/historico.php').'?'.escapar(http_build_query($f+['tipo_lista'=>'alertas'])) ?>" data-offset="5" data-destino="historico-alertas">Mostrar mais</button><?php endif ?><a href="<?= urlApp('app/views/graficos/alerta.php').'?'.escapar(http_build_query($escopoHistorico)) ?>">Consultar todos os alertas</a></section>
<section class="card"><h2>Leituras registradas</h2><p><?= $historicoLeituras['total'] ?> leituras no período. Carregamento de 25 registros por vez.</p><div class="table-wrapper"><table><thead><tr><th>Data e horário</th><th>Sensor</th><th>Estoque</th><th>Valor</th><th>Estado ambiental</th></tr></thead><tbody id="historico-leituras"><?php foreach($historicoLeituras['registros'] as $l)require __DIR__.'/linha_leitura.php'; ?></tbody></table></div><?php if(!$historicoLeituras['total']): ?><p class="estado-vazio">Nenhuma leitura encontrada.</p><?php endif ?><?php if($historicoLeituras['total']>25): ?><button type="button" class="btn-secundario" data-carregar="<?= urlApp('routes/historico.php').'?'.escapar(http_build_query($f+['tipo_lista'=>'leituras'])) ?>" data-offset="25" data-destino="historico-leituras">Mostrar mais</button><?php endif ?></section>
<script>Object.entries(<?= jsonParaScript($series) ?>).forEach(([tipo,s])=>criarGraficoAmbiental('historico-'+tipo,s.pontos));</script>
<?php endif ?>
